package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.os.*;
import android.net.Uri;
import android.database.Cursor;
import java.lang.reflect.Field;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import io.github.polestarcn.bridge.CarLinkBridgeContract;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class Beta38ProtocolTest {
 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);OppoDeviceIntegration.setEnabled(a,true);}
 @After public void stop(){BridgeCommandRequests.cancelAll();base.stop();}
 private void ready()throws Exception{Field f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(model,true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="ACTUAL-TEST-VEHICLE-123";model.snapshot=new VehicleSnapshot("Polestar 2","masked",42,170,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");}
 private Bundle request(String action,String id){Bundle b=new Bundle();b.putString(CarLinkBridgeContract.COMMAND,action);b.putString(CarLinkBridgeContract.REQUEST,id);return b;}
 @Test public void fourNumericEventsRequireExplicitDirection(){for(int code:new int[]{1001,1002,1003}){assertNull(OppoCarLinkCommandMap.bridgeAction(code,new Bundle()));Bundle b=new Bundle();b.putBoolean(CarLinkBridgeContract.TARGET,true);assertNotNull(OppoCarLinkCommandMap.bridgeAction(code,b));b.putBoolean(CarLinkBridgeContract.TARGET,false);assertNotNull(OppoCarLinkCommandMap.bridgeAction(code,b));}assertEquals("honk-flash",OppoCarLinkCommandMap.bridgeAction(1004,null));}
 @Test public void actionNamesAreExactAndNeverGuessAirOrUnknownWords(){assertNull(OppoCarLinkCommandMap.bridgeAction(1001,request("factory-reset","x")));assertNull(OppoCarLinkCommandMap.bridgeAction(1002,request("air-start","x")));assertEquals("climate-stop",OppoCarLinkCommandMap.bridgeAction(-1,request("climate_off","x")));assertEquals("windows-open",OppoCarLinkCommandMap.bridgeAction(-1,request("window_vent","x")));}
 @Test public void signedOutHasNoInventedVehicleOrState(){Bundle b=OppoCarLinkProtocol.read(a,CarLinkBridgeContract.SESSION);assertFalse(b.getBoolean("hasCarBinding"));assertEquals("",b.getString("vehicle_vin"));assertFalse(b.containsKey("soc_percent"));assertFalse(b.containsKey("is_locked"));}
 @Test public void cacheIsTypedAndExposesOnlySyntheticIdentity()throws Exception{ready();Bundle b=OppoCarLinkProtocol.read(a,CarLinkBridgeContract.SNAPSHOT);assertTrue(b.getBoolean("hasCarBinding"));assertTrue(b.getBoolean("soc_percent_known"));assertEquals(42,b.getInt("soc_percent"));assertEquals(170,b.getInt("range_km"));assertTrue(b.getBoolean("is_locked"));assertFalse(b.toString().contains(model.selected.vin));}
 @Test public void uriQueryHonorsProjectionAndRejectsUnknownColumns()throws Exception{ready();Uri u=Uri.parse("content://"+CarLinkBridgeContract.AUTHORITY+"/"+CarLinkBridgeContract.BIND_PATH);try(Cursor c=OppoCarLinkProtocol.query(a,u,new String[]{"is_bound","brand","vin"})){assertTrue(c.moveToFirst());assertEquals(1,c.getInt(0));assertEquals("Polestar",c.getString(1));assertNotEquals(model.selected.vin,c.getString(2));assertEquals(3,c.getColumnCount());}try{OppoCarLinkProtocol.query(a,u,new String[]{"token"});fail();}catch(IllegalArgumentException expected){}}
 @Test public void rootCursorDoesNotTurnMissingStateIntoZero(){try(Cursor cursor=OppoCarLinkProtocol.query(a,PsAssistantBridgeProvider.URI,new String[]{"has_binding","soc","is_locked","synthetic_identifiers"})){assertTrue(cursor.moveToFirst());assertEquals(0,cursor.getInt(0));assertTrue(cursor.isNull(1));assertTrue(cursor.isNull(2));assertEquals(1,cursor.getInt(3));}}
 @Test public void dispatchRejectsOfflineAndDoesNotReportSuccess(){Bundle b=OppoCarLinkProtocol.dispatch(a,request("unlock","offline-38"));assertFalse(b.getBoolean("accepted"));assertFalse(b.getBoolean("exec_success"));assertEquals(OperationState.NOT_SENT,model.operation);}
 @Test public void duplicateIdIsConsumedOnceAndConflictRejected()throws Exception{ready();Bundle in=request("unlock","duplicate-38");Bundle first=OppoCarLinkProtocol.dispatch(a,in);assertTrue(first.getBoolean("accepted"));assertFalse(first.getBoolean("exec_success"));Bundle second=OppoCarLinkProtocol.dispatch(a,in);assertTrue(second.getBoolean("duplicate"));assertEquals("request-id-conflict",OppoCarLinkProtocol.dispatch(a,request("lock","duplicate-38")).getString("reason"));Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(OperationState.NOT_SENT,model.operation);}
 @Test public void callbackDistinguishesAuthorizationAndCancellation()throws Exception{ready();List<Bundle> replies=new ArrayList<>();Bundle in=request("lock","callback-38");in.putParcelable(CarLinkBridgeContract.RECEIVER,new ResultReceiver(new Handler(Looper.getMainLooper())){@Override protected void onReceiveResult(int code,Bundle b){replies.add(b);}});assertTrue(OppoCarLinkProtocol.dispatch(a,in).getBoolean("accepted"));Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(replies.isEmpty());assertEquals("awaiting-authorization",replies.get(0).getString("reason"));assertNotNull(replies.get(0).getParcelable("authorizationIntent"));assertFalse(replies.get(0).getBoolean("exec_success"));BridgeCommandRequests.cancelAll();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(replies.get(replies.size()-1).getBoolean("terminal"));assertFalse(replies.get(replies.size()-1).getBoolean("vehicleConfirmed"));}
 @Test public void unsupportedTemperatureNeverSilentlyFallsBack()throws Exception{ready();Bundle b=request("climate_on","temp-38");b.putFloat("target_temp",26);assertEquals("request-temperature-not-supported",OppoCarLinkProtocol.dispatch(a,b).getString("reason"));}
 @Test public void stateAndVinAreRevalidatedBeforeQueuedExecution()throws Exception{ready();Bundle in=request("lock","race-38");assertTrue(OppoCarLinkProtocol.dispatch(a,in).getBoolean("accepted"));model.selected.vin="CHANGED-VEHICLE";Shadows.shadowOf(Looper.getMainLooper()).idle();Bundle done=OppoCarLinkProtocol.dispatch(a,in);assertFalse(done.getBoolean("accepted"));assertEquals(OperationState.NOT_SENT,model.operation);}
 @Test public void messengerReadUsesPublishedProtocolWithoutWrites()throws Exception{
  android.app.Service service=Robolectric.buildService(OppoCarLinkBridgeService.class).create().get();List<Bundle> replies=new ArrayList<>();Messenger client=new Messenger(service.onBind(new android.content.Intent()));Message m=Message.obtain();Bundle data=new Bundle();data.putString("method",CarLinkBridgeContract.SESSION);m.setData(data);m.sendingUid=android.os.Process.myUid();m.replyTo=new Messenger(new Handler(Looper.getMainLooper()){@Override public void handleMessage(Message msg){replies.add(msg.getData());}});client.send(m);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,replies.size());assertEquals(1,replies.get(0).getInt("bridgeProtocolVersion"));assertFalse(replies.get(0).getBoolean("hasCarBinding"));service.onDestroy();
 }
}
